import java.util.Scanner;

public class Main {

	static Scanner sc = new Scanner(System.in);
	public static void main(String[] args) {

		while(sc.hasNext()) {
			int a = sc.nextInt();
			int b = sc.nextInt();

			System.out.printf("%d %d\n",gcd(a, b) ,lcm(a, b));
		}
		sc.close();

	}

	private static long lcm(int i, int j) {
		long lcm = i / gcd(i, j) * j;
		return lcm;
	}

	private static int gcd(int x, int y) {
		int x_tmp = 0;

		do {
			x_tmp = x;

			x = y;
			y = x_tmp % y;
		}while(y > 0);

		int gcd = x;

		return gcd;
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    private static final String blank = " ";

    public static void main(String[] args) {

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

        String input = null;

        try {
            while ((input = in.readLine()) != null) {

                String[] problemData = input.split(blank);

                int num1 = Integer.valueOf(problemData[0]);
                int num2 = Integer.valueOf(problemData[1]);

                int gcd = resolveGcd(num1, num2);
                long lcm = (long) (num1 / gcd * num2);

                System.out.println(gcd + blank + lcm);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private static int resolveGcd(int num1, int num2) {

        int result = num1 % num2;

        if (result == 0) {
            return num2;
        }

        return resolveGcd(num2, result);
    }
}

