					for(i = b / 2; i > 0; i--){
						if(a % i == 0 && b % i == 0){
							break;
						}
					}
					System.out.println(i + " " + a1 );
				}
			}
			else if(a < b){
				for(;;){
					if(b1 % a == 0){
						break;
					}
					b1 += b;
				}
				if(b % a == 0){
					System.out.println(a + " " + b1 );
				}
				else{
					for(i = a / 2; i > 0; i--){
						if(a % i == 0 && b % i == 0){
							break;
						}
					}
					System.out.println(i + " " + b1 );
				}	
			}
			else{
				System.out.println(b + " " + b1 );
			}
		}
	}

}

