        System.out.println(gcd(x,y));
    }

    static int gcd(int x, int y){
        int a = Math.max(x, y);
        int b = Math.min(x, y);

        while(b > 0){
            int c = a % b;
            a = b;
            b = c;
        }
        return a;
    }

