            int[] s = new int[n];

            int sum = 0;

            for(int i =0; i < n; i++){
                s[i] = sc.nextInt();
                sum = sum + s[i];
            }
            double ave = 0, var = 0;

            ave = sum / (double)n;

            double sum2 = 0;

            for(int k = 0; k < n; k++){
                sum2 = sum2 + (s[k] - ave) * (s[k] - ave);
            }

            var = sum2 / (double)n;

            System.out.printf("%.8f\n",Math.sqrt(var));

        }

    }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		double dev = 0.0;
		Scanner sc = new Scanner(System.in);

		do {
			int n = sc.nextInt();

			if (n == 0) {
				break;
			}

			int[] grade = new int[n];

			for (int i = 0; i < n; i++) {
				grade[i] = sc.nextInt();
			}

			dev = deviation(grade);

			System.out.println(dev);


		}while(true);

		sc.close();
	}

	private static double deviation(int[] grade) {
		double deviation = 0;

		for (int i = 0; i < grade.length; i++) {
			deviation += Math.pow( grade[i] - average(grade) , 2);
		}

		deviation /= grade.length;
		deviation = Math.sqrt(deviation);
		return deviation;
	}

	public static double average(int[] grade) {
		double average = 0;

		for (int i = 0; i < grade.length; i++) {
			average += grade[i];
		}

		average /= grade.length;

		return average;
	}


}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		List<Double> list = new ArrayList<Double>();

		while (true) {
			int n = scan.nextInt();
			if (n == 0) {
				break;
			}

			int[] s = new int[n];
			int sum = 0;
			for (int i = 0; i < n; i++) {
				s[i] = scan.nextInt();
				sum += s[i];
			}
			double m = (double)sum / n;

			double alpha = 0;
			for (int i = 0; i < n; i++) {
				alpha += (s[i] - m) * (s[i] - m);
			}
			alpha = Math.sqrt(alpha / n);
			list.add(alpha);
		}

		for (Double alpha : list) {
			System.out.println(alpha);
		}

		scan.close();
	}

}

