			for (char c : ch) {
				if ('a' <= c && c <= 'z') {
					counter[c - 'a']++;
				}
			}
		}

		for (int i = 0; i < counter.length; i++) {
			System.out.println((char) ('a' + i) + " : " + counter[i]);
		}

	}
}

