            long LIMIT = 1000000000000000000L;
            for (int i = 0; i < N; i++) {
                if (a[i] <= LIMIT / total) {
                    total *= a[i];
                } else {
                    System.out.println(-1);
                    return;
                }
            }
            System.out.println(total);
        }
    }
}

