	for(int i = 0; i <= n; i++) {
		flg[i] = false;
	}
	int seito = 0;
	int penal = 0;
	int[] penal_loop = new int[n+1];



	for(int j = 0; j < m; j++) {
		// i番目の問題がまだ正解していないとき
		if(flg[pi[j]] == false) {
