		Scanner sc = new Scanner(System.in);
		int x = sc.nextInt();
		while(true) {
			if(prime(x)) {
				System.out.println(x);
				break;
			}
			x++;
		}

	}
	public static boolean prime(int x) {
		for(int i = 2;i <= Math.sqrt(x); i++) {
			if(x % i ==0) return false;
		}
		return true;
	}
}

