    static class Task {
        public void solve(int testNumber, Scanner sc, PrintWriter pw) {
            int x = sc.nextInt(), y = sc.nextInt();
            pw.println(lcm(x, y));
        }

        private long lcm(int x, int y) {
            return 1l * x * y / gcd(x, y);
