        System.out.println(ans);
    }

    static long gcd(long a, long b) {
        if (b == 0)
            return a;
        return gcd(b, a % b);
    }

    static long f(long n, long c, long d) {
        long x = n;
        x -= n / c;
        x -= n / d;
        long tmp = c / gcd(c, d) * d;
        x += n / tmp;
        return x;
    }
}

