	    String s=in.readString();
	    int ctr=0;
	    Stack<Character> st=new Stack<>();
	    st.push(s.charAt(0));
	    for(int i=1;i<s.length();i++)
	    {
	    	char ch=s.charAt(i);
	    	if(st.isEmpty())
	    		st.push(ch);
	    	else 
	    		if(ch==st.peek())
	    		st.push(ch);
	    	else
	    	{
	    		st.pop();ctr+=2;
	    	}
	    }
	    out.printLine(ctr);

	}


