        while (n-- > 0) {
            int nt = sc.nextInt();
            int nx = sc.nextInt();
            int ny = sc.nextInt();

            int dist = Math.abs(nx-x) + Math.abs(ny-y);

            if (nt % 2 != (nx+ny) % 2) {
                System.out.println("No");
                return;
            }

            if (nt - t < dist) {
                System.out.println("No");
                return;
            }

            t = nt;
            x = nx;
            y = ny;
        }


        System.out.println("Yes");
    }
}

