public class Main {
    public static void main(String args[]){
        Scanner scanner = new Scanner(System.in);
        int N  = scanner.nextInt();
        int[] count = new int[8];
        int over = 0;
        for(int i=0;i<8;i++){
            count[i] = 0;
        }
        for(int i=0; i<N; i++){
            int a = scanner.nextInt();
            if(a <= 399){
                count[0] = Math.min(1, count[0] + 1); 
            }else if(a<=799){
                count[1] = Math.min(1, count[1] + 1); 
            }else if(a<=1199){
                count[2] = Math.min(1, count[2] + 1); 
            }else if(a<=1599){
                count[3] = Math.min(1, count[3] + 1);
            }else if(a<=1999){
                count[4] = Math.min(1, count[4] + 1);
            }else if(a<=2399){
                count[5] = Math.min(1, count[5] + 1);
            }else if(a<=2799){
                count[6] = Math.min(1, count[6] + 1);
            }else if(a<=3199){
                count[7] = Math.min(1, count[7] + 1);
            }else{
                over++;
            }
        }
        int min = 0;
        for(int i=0; i<8; i++){
            min += count[i];
        }
        int max = min+over;
        if(min==0 && over>=1){
            min=1;
        }
        System.out.println(String.valueOf(min) + " " + String.valueOf(max));
    }
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int[] color = new int[8];
    int strong = 0;
    for(int i = 0; i < N; i++) {
      int a = sc.nextInt();
      int c = -1;
      if(a < 400) c = 0;
      if((a >= 400) && (a < 800)) c = 1;
      if((a >= 800) && (a < 1200)) c = 2;
      if((a >= 1200) && (a < 1600)) c = 3;
      if((a >= 1600) && (a < 2000)) c = 4;
      if((a >= 2000) && (a < 2400)) c = 5;
      if((a >= 2400) && (a < 2800)) c = 6;
      if((a >= 2800) && (a < 3200)) c = 7;
      if(c != -1) color[c]++;
      if(c == -1) strong++;
    }
    int vari = 0;
    for(int i = 0; i < 8; i++) {
      if(color[i] > 0) vari++;
    }
    int min = 0;
    int max = 0;
    if(vari == 0) {
      min = 1;
      max = N;
    } else {
      min = vari;
      max = vari + strong;
    }
    System.out.println(min + " " + max);
  }
}

