		for(int x=0;x<=k && x<=s;++x) {
			for(int y=0;y<=k && y+x<=s;++y) {
				if(s-x-y<=k) ++ans;
			}
		}
		pw.print(ans);
		pw.print('\n');
		pw.flush();
	}
}

